import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"Research Runtime Center V4","description":"","frontmatter":{"title":"Research Runtime Center V4","outline":"deep"},"headers":[],"relativePath":"zh/runtime/v4.md","filePath":"zh/runtime/v4.md","lastUpdated":1785823690000}'),n={name:"zh/runtime/v4.md"};function l(p,a,o,d,r,c){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="research-runtime-center-v4" tabindex="-1">Research Runtime Center V4 <a class="header-anchor" href="#research-runtime-center-v4" aria-label="Permalink to &quot;Research Runtime Center V4&quot;">​</a></h1><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>Research Runtime Center V4 是数字研究员的运营中心：三条研究情报管线共同为三个栏目发现选题，上午推进研究，下午生产完整报告，晚上完成 GitHub 与网站发版。</p><h2 id="研究情报系统" tabindex="-1">研究情报系统 <a class="header-anchor" href="#研究情报系统" aria-label="Permalink to &quot;研究情报系统&quot;">​</a></h2><p>“从哪里找”和“研究什么”是两个不同维度。</p><h3 id="三条来源情报管线" tabindex="-1">三条来源情报管线 <a class="header-anchor" href="#三条来源情报管线" aria-label="Permalink to &quot;三条来源情报管线&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill 01-P — AI 平台变更情报发现</span></span>
<span class="line"><span>Skill 01-G — GitHub 工程情报发现</span></span>
<span class="line"><span>Skill 01-R — 论文与研究成果情报发现</span></span></code></pre></div><p>三条管线共同形成统一信号池，完成跨来源去重后，再由 Skill 02 进行三栏研究筛选。</p><h3 id="ai-平台一级观察范围" tabindex="-1">AI 平台一级观察范围 <a class="header-anchor" href="#ai-平台一级观察范围" aria-label="Permalink to &quot;AI 平台一级观察范围&quot;">​</a></h3><p>每日固定检查：</p><ul><li>OpenAI / ChatGPT / Codex；</li><li>Anthropic / Claude / Claude Code；</li><li>Google / Gemini；</li><li>Cursor；</li><li>GitHub Copilot；</li><li>Microsoft Copilot Platform。</li></ul><p>检查对象包括官方 Release Notes、文档、论坛或社区、官方 GitHub、状态页、企业控制、权限和产品边界。需要登录的渠道必须记录为受限，不能冒充“已检查无更新”。</p><h3 id="github-工程雷达" tabindex="-1">GitHub 工程雷达 <a class="header-anchor" href="#github-工程雷达" aria-label="Permalink to &quot;GitHub 工程雷达&quot;">​</a></h3><p>GitHub 不做不可能的全量扫描，而是采用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>70% 固定组织与仓库 Watchlist</span></span>
<span class="line"><span>20% 固定主题 × 变化类型查询</span></span>
<span class="line"><span>10% 有边界的新项目探索</span></span></code></pre></div><p>扫描 Release、Tag、已合并 PR、高价值 Issue、Discussion、安全公告和架构、测试、Benchmark 等关键文件的增量变化。</p><h3 id="论文与研究成果雷达" tabindex="-1">论文与研究成果雷达 <a class="header-anchor" href="#论文与研究成果雷达" aria-label="Permalink to &quot;论文与研究成果雷达&quot;">​</a></h3><p>观察论文、预印本、技术报告、Benchmark、数据集、System Card、Model Card、标准以及关联代码与评估工具。摘要或厂商宣传不能单独形成工程结论。</p><p><a href="/joinwell52/zh/runtime/research-intelligence">查看研究情报系统 V1.0</a></p><h2 id="三个栏目" tabindex="-1">三个栏目 <a class="header-anchor" href="#三个栏目" aria-label="Permalink to &quot;三个栏目&quot;">​</a></h2><p>每日 10:00 的 Research Runtime Queue 必须分别对以下栏目作出决定：</p><ol><li><strong>数字员工</strong>：岗位、职责、工作流、运行、治理、恢复、交付与评估；</li><li><strong>行业架构</strong>：主要 AI 平台的产品、Workspace、Agent 运行模式、控制平面、权限、连接器、企业控制与产品边界；</li><li><strong>开源工程</strong>：开源运行时、协议、SDK、工具、基准、恢复、测试与可观测性工程。</li></ol><p>每个栏目必须显示：</p><ul><li>今日选题，或“未选题”；</li><li>选题原因或未选题原因；</li><li>主要来源；</li><li>优先级与生命周期；</li><li>下一步。</li></ul><h2 id="每日班次" tabindex="-1">每日班次 <a class="header-anchor" href="#每日班次" aria-label="Permalink to &quot;每日班次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>班次</th><th>工作成果</th></tr></thead><tbody><tr><td>09:00</td><td>Research Runtime Engine</td><td>严格推进一个受治理生命周期转换。</td></tr><tr><td>10:00</td><td>Research Runtime Queue</td><td>执行三条情报管线、跨来源去重、候选评分与三栏选题计划。</td></tr><tr><td>11:00</td><td>Research Runtime Knowledge</td><td>合格研究笔记的知识准入与架构候选。</td></tr><tr><td>15:00</td><td><strong>Research Runtime Production</strong></td><td>完成中英文报告、配图、引用与出版编辑，形成 Publication Candidate。</td></tr><tr><td>20:00</td><td>Research Runtime Publication</td><td>发布完整候选、更新索引和网站、提交并验证 GitHub。</td></tr></tbody></table><p>周一 12:00 另有架构评审；周日 20:30 生成每周综合；周三 10:00 运行学术研究。</p><h2 id="_10-00-情报发现与选题班次" tabindex="-1">10:00 情报发现与选题班次 <a class="header-anchor" href="#_10-00-情报发现与选题班次" aria-label="Permalink to &quot;10:00 情报发现与选题班次&quot;">​</a></h2><p>Queue 完成的标准不再是“搜索到了一条新闻”，而是：</p><ul><li>三条情报管线均有覆盖结果；</li><li>所有到期来源已检查、明确受限或记录失败原因；</li><li>同一变化在平台、GitHub 和论文来源中完成去重；</li><li>每个入选对象只有一个主栏目；</li><li>三个栏目均作出“已选题”或“未选题”决定；</li><li>情报运行记录与三栏计划中的选题 ID 一致。</li></ul><h2 id="_15-00-生产班次" tabindex="-1">15:00 生产班次 <a class="header-anchor" href="#_15-00-生产班次" aria-label="Permalink to &quot;15:00 生产班次&quot;">​</a></h2><p>下午班次执行已有 Research Skills：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill 05 — Research Writing</span></span>
<span class="line"><span>→ Skill 06 — Visualization</span></span>
<span class="line"><span>→ Skill 07 — Evidence &amp; Citation</span></span>
<span class="line"><span>→ Skill 08 — Publication Editing</span></span></code></pre></div><p>输出不是半成品草稿，而是完整的 <strong>Publication Candidate（出版候选）</strong>：</p><ul><li>中文 Markdown 完整；</li><li>英文 Markdown 完整；</li><li>元数据与栏目归属正确；</li><li>配图完成，或明确说明不需要配图；</li><li>证据与引用完成校验；</li><li>出版编辑完成；</li><li>尚未进入公共文章目录。</li></ul><h2 id="_20-00-发版班次" tabindex="-1">20:00 发版班次 <a class="header-anchor" href="#_20-00-发版班次" aria-label="Permalink to &quot;20:00 发版班次&quot;">​</a></h2><p>20:00 只负责发布，不重新研究或写作：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Publication Candidate</span></span>
<span class="line"><span>→ 中英文公共文章</span></span>
<span class="line"><span>→ Metadata / Index / Website</span></span>
<span class="line"><span>→ GitHub Commit</span></span>
<span class="line"><span>→ Commit Verify</span></span>
<span class="line"><span>→ Release</span></span></code></pre></div><p>候选未通过发版门禁时，应退回 Production 或更早的研究阶段。</p><h2 id="四类权威运行产物" tabindex="-1">四类权威运行产物 <a class="header-anchor" href="#四类权威运行产物" aria-label="Permalink to &quot;四类权威运行产物&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/YYYY/MM/YYYY-MM-DD-runtime.md</span></span></code></pre></div><p>记录每个班次的状态、输入、工作成果、输出、下一步和 GitHub 证据。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/intelligence/runs/YYYY/MM/YYYY-MM-DD-intelligence.json</span></span></code></pre></div><p>记录三条情报管线的覆盖、失败、信号、候选与三栏筛选决定。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/plans/YYYY/MM/YYYY-MM-DD-plan.json</span></span></code></pre></div><p>记录三个栏目的每日选题决定，并必须与情报运行记录一致。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>research/runtime/candidates/YYYY/MM/YYYY-MM-DD-candidates.json</span></span></code></pre></div><p>记录 15:00 形成的完整出版候选，供 20:00 发版使用。</p><h2 id="完成率" tabindex="-1">完成率 <a class="header-anchor" href="#完成率" aria-label="Permalink to &quot;完成率&quot;">​</a></h2><p>只有 <code>Completed</code> 计入完成率：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>完成率 = 已完成任务数 ÷ 当日计划任务数</span></span></code></pre></div><p><code>Waiting</code>、<code>Running</code> 尚未完成；<code>Skipped</code>、<code>Blocked</code>、<code>Failed</code> 虽已终止，也不算完成。</p><h2 id="最高原则" tabindex="-1">最高原则 <a class="header-anchor" href="#最高原则" aria-label="Permalink to &quot;最高原则&quot;">​</a></h2><blockquote><p>三条情报管线共同服务三个研究栏目。</p></blockquote><blockquote><p>已检查但没有重要变化，与没有检查，是两个不同事实。</p></blockquote><blockquote><p>每个定时任务都必须汇报实际工作成果，而不是只汇报“执行完成”。</p></blockquote><blockquote><p>下午生产完整报告，晚上只负责正式发版。</p></blockquote><blockquote><p>没有 Runtime Record 和 Commit Verify 的发布，不属于正式运行结果。</p></blockquote>`,58)])])}const b=e(n,[["render",l]]);export{u as __pageData,b as default};
